import java.util.*;

public class Main {
    static int findKthNumber(int n, int k) {
        List<String> nums = new ArrayList<>();
        for (int i = 1; i <= n; i++) nums.add(String.valueOf(i));   // generate every number as a string
        Collections.sort(nums);                                          // sort lexicographically
        return Integer.parseInt(nums.get(k - 1));
    }
}

