def find_kth_number(n, k):
    def count_steps(first, last):
        steps = 0
        while first <= n:
            steps += min(n + 1, last) - first        # numbers in this level of the subtree
            first *= 10
            last *= 10
        return steps

    curr = 1
    k -= 1                                              # curr = 1 is itself the first step
    while k > 0:
        steps = count_steps(curr, curr + 1)
        if steps <= k:
            curr += 1                                     # skip the whole subtree, move to next sibling
            k -= steps
        else:
            curr *= 10                                     # descend into the first child
            k -= 1
    return curr

